390:   function resolveNext(spec) {
391:     if (!spec) return null;
392:     if (EVENTS[spec]) return spec;
393:     if (spec.startsWith('pool:')) {
394:       const key = spec.slice(5);
395:       const list = (POOLS[key] || POOLS.clue).filter((id) => id !== s.current);
396:       const unseen = list.filter((id) => !s.seen[id]);
397:       const arr = unseen.length && Math.random() < 0.7 ? unseen : list;
398:       return arr[rnd(arr.length)] || POOLS.clue[0];
399:     }
400:     return null;
401:   }
