403:   function pick(index) {
404:     if (lock) return;
405:     const ev = EVENTS[s.current];
406:     if (!ev) return;
407:     const ch = ev.choices[index];
408:     if (!ch) return;
409:     lock = true;
410:     $$('#choices .choice').forEach((b) => (b.disabled = true));
411: 
412:     const fb = [];
413:     const beforeMoral = s.moral;
414:     applyEffects(ch, fb);
415: 
416:     if (ch.run) {
417:       const line = ch.run(s);
418:       if (line) fb.push(line);
419:     }
420:     if (ch.endLine) {
421:       s.finaleLine = typeof ch.endLine === 'function' ? ch.endLine(s) : ch.endLine;
422:     }
423:     footTax();
424: 
425:     if (ch.fx && ch.fx.moral >= 5) fb.push('İçindeki oda biraz genişledi.');
426:     if (ch.fx && ch.fx.moral <= -5 || s.moral < beforeMoral - 6) fb.push('Duygusal sınırın biraz daha inceldi.');
427:     if (ch.fx && ch.fx.clues) fb.push('Dosyada bir parça daha netleşti.');
428: 
429:     s.log.push({ night: s.night, title: ev.title, choice: ch.label, id: s.current });
430: 
431:     let nextId = ch.next ? resolveNext(ch.next) : null;
432: 
433:     if (nextId && s.queue.length) {
434:       const upcoming = s.queue[0];
435:       const upEv = EVENTS[upcoming];
436:       if ((!upEv || upEv.cat !== 'end') && !s.queue.slice(1).includes(nextId) && nextId !== s.current) {
437:         s.queue[0] = nextId;
438:       }
439:     }
440: 
441:     // olay olayı tetiklesin: kritik eşikler yeni bir sahne açar
442:     if (s.chain < 2 && s.queue.length) {
443:       let chainId = null;
444:       if (s.moral <= 11 && s.current !== 'i_agla') chainId = 'i_agla';
445:       else if (s.smell >= 3 && s.current !== 'i_koku') chainId = 'i_koku';
446:       else if (s.pain >= 84 && s.current !== 'i_tayt' && s.current !== 'i_topuk') chainId = 'i_tayt';
447:       if (chainId && !s.queue.includes(chainId) && Math.random() < 0.75) {
448:         s.queue.unshift(chainId);
449:         s.chain += 1;
450:       }
451:     }
452: 
453:     s.minutes += 3 + rnd(6);
454:     updateHUD();
455:     save();
456: 
457:     // sonuçları bir sonraki kartta göster
458:     const pending = fb.slice(0, 3);
459:     setTimeout(() => {
460:       if (!s.queue.length) { endNight(pending); return; }
461:       nextFromQueue();
462:       if (pending.length) {
463:         $('#evOutcome').innerHTML = pending.map((line, i) =>
464:           `<div class="outcome-line ${i === 0 && (s.moral < 30) ? 'bad' : 'good'}">${esc(line)}</div>`).join('');
465:       }
466:       updateHUD();
467:     }, 260);
468:   }
