470:   function applyEffects(ch, fb) {
471:     const f = ch.fx || {};
472:     const numericKeys = ['moral', 'energy', 'pain', 'clues', 'wet', 'sand', 'smell'];
473:     numericKeys.forEach((k) => {
474:       if (f[k] == null) return;
475:       const cap = (k === 'wet' || k === 'sand' || k === 'smell') ? 3 : 100;
476:       const prev = s[k] || 0;
477:       s[k] = clamp(prev + f[k], 0, cap);
478:       const d = s[k] - prev;
479:       if (k === 'wet' && d > 0) fb.push(`${SOCK(s).name} ıslandı.`);
480:       if (k === 'sand' && d > 0) fb.push('Ayakkabının içine kum doldu.');
481:       if (k === 'smell' && d > 0) fb.push('Burnuna ince bir tuz kokusu geldi.');
482:       if (k === 'pain' && d >= 6) fb.push('Ayakların sızlıyor.');
483:       if (k === 'energy' && d <= -6) fb.push('Enerjin azaldı.');
484:     });
485:     if (f.rank) {
486:       s.xp = Math.max(0, s.xp + (f.rank > 0 ? f.rank * 2 : f.rank * 2));
487:     }
488:     if (f.cry) s.cried += 1;
489:     if (f.tag) s.flags[f.tag] = (s.flags[f.tag] || 0) + 1;
490:     s.moral = clamp(s.moral);
491:   }
