690:       <stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".38" stop-color="#fff" stop-opacity=".22"/><stop offset=".55" stop-color="#fff" stop-opacity="0"/>
691:     </linearGradient>`;
692: 
693:     const leg = (cx, mirror) => {
694:       const d = mirror ? 1 : -1;
695:       const top = isBoot ? 50 : -8;
696:       const legPath = `M${cx - 17} ${top} C${cx - 21} 34 ${cx - 20} 74 ${cx - 16} 106 L${cx + 16} 106 C${cx + 20} 74 ${cx + 20} 34 ${cx + 17} ${top} Z`;
697:       let shoeShape = '';
698:       if (isHeel) {
